# Version script for libvpx_decoder.so
#
# Only the public C-API functions declared in vpx_decoder_api.h need export.
# These functions are wrapped in extern "C", so they have no C++ name mangling.
#
# Internal implementation details (C++ classes, helper functions, static libs)
# are hidden via 'local: *;'.

VPX_DECODER_1.0 {
  global:
    extern "C" {
      /* Public API: Get decoder capability list */
      GetVpxDecoderCapabilityList;

      /* Public API: Create decoder instance by name */
      CreateVpxDecoderByName;
    };

  local:
    *;
};

